<script setup lang="ts">
import WorkspaceSyncPanel from './WorkspaceSyncPanel.vue';
import { computed, onUnmounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { ElButton, ElTable, ElTableColumn, ElTag } from 'element-plus';
import { projectSummaries } from '#/api/creative-video/summary';
import { stages } from '#/api/creative-video';
import { approvals } from '#/api/creative-video/approvals';
const route=useRoute();const router=useRouter();const rows=ref(projectSummaries());
const timer=setInterval(()=>rows.value=projectSummaries(),2000);onUnmounted(()=>clearInterval(timer));
const visible=computed(()=>rows.value.filter(r=>!r.project.deleted&&!r.project.archived));
const detail=computed(()=>rows.value.find(r=>String(r.project.id)===route.params.id));
const steps=['ingest','understanding','angles','script','storyboard','animatic','generate','render'];
function resume(id:number,stage:number){void router.push(`/studio/${id}/${steps[stage]}`);}
</script>
<template><div class="overview"><ElTag type="warning">MOCK · 当前浏览器演示数据</ElTag><template v-if="route.params.id"><template v-if="detail"><h1>{{ detail.project.name }}</h1><p>{{ detail.project.productName || '产品名称待补充' }} · {{ detail.project.url || '尚未输入网址' }}</p><ElTag>{{ stages[detail.project.stage] }}</ElTag><div class="metrics"><article><b>{{ detail.approved }}/{{ detail.shots }}</b>已采用镜头</article><article><b>{{ detail.spent }}</b>已结算积分</article><article><b>{{ detail.held }}</b>冻结积分</article><article><b>{{ detail.renders }}</b>合成版本</article></div><p>渠道：{{ detail.project.channels?.join('、') || '待配置' }} · {{ detail.project.duration }} 秒 · {{ detail.project.aspect || '未配置画幅' }}</p><p>受众：{{ detail.project.audience || '待核实' }}</p><p>创建于 {{ detail.project.createdAt || '历史项目' }}</p><ElButton type="primary" :disabled="detail.project.deleted" @click="resume(detail.project.id,detail.project.stage)">继续创作</ElButton><ElButton @click="router.push('/tasks')">查看任务</ElButton><ElButton @click="router.push('/billing')">查看账单</ElButton><h2>阶段确认记录</h2><p v-for="a in approvals(detail.project.id)" :key="a.stage">{{ stages[a.stage] }} · {{ a.date }}</p></template><template v-else><WorkspaceSyncPanel/><h1>项目不存在</h1><ElButton @click="router.push('/projects')">返回项目中心</ElButton></template></template>
<template v-else><WorkspaceSyncPanel/><h1>让产品的下一个故事，从这里开始。</h1><p>查看创作进度，处理待审镜头，掌握每一笔模拟费用。</p><div class="metrics"><article><b>{{ visible.length }}</b>进行中的项目</article><article><b>{{ rows.reduce((n,r)=>n+r.running,0) }}</b>生成中任务</article><article><b>{{ rows.reduce((n,r)=>n+r.reconciling,0) }}</b>待核对费用</article><article><b>{{ rows.reduce((n,r)=>n+r.spent,0) }}</b>累计模拟消费</article></div><ElButton type="primary" @click="router.push('/projects/new')">＋ 新建项目</ElButton><ElButton @click="router.push('/projects')">全部项目</ElButton><h2>最近创作</h2><ElTable :data="visible.slice().sort((a,b)=>b.project.id-a.project.id).slice(0,8)"><ElTableColumn prop="project.name" label="项目"/><ElTableColumn label="阶段"><template #default="{row}">{{ stages[row.project.stage] }}</template></ElTableColumn><ElTableColumn label="镜头审核"><template #default="{row}">{{ row.approved }}/{{ row.shots }}</template></ElTableColumn><ElTableColumn prop="spent" label="模拟消费"/><ElTableColumn label="操作"><template #default="{row}"><ElButton @click="router.push(`/projects/${row.project.id}`)">项目详情</ElButton><ElButton @click="resume(row.project.id,row.project.stage)">继续创作</ElButton></template></ElTableColumn></ElTable><p v-if="!visible.length">尚无项目，创建第一个创意项目开始体验。</p><p>效果分析：真实渠道数据尚未接入，不展示虚构转化成绩。</p></template></div></template>
<style scoped>.overview{padding:32px;background:var(--el-bg-color);margin:24px;border-radius:16px}h1{font-size:30px;font-weight:700;margin:24px 0}h2{font-size:20px;font-weight:600;margin:30px 0 16px}p{color:var(--el-text-color-secondary);line-height:1.9;margin:16px 0}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin:28px 0}.metrics article{padding:24px;background:var(--el-fill-color-light);border-radius:12px;color:var(--el-text-color-secondary)}b{display:block;font-size:32px;color:var(--el-text-color-primary);margin-bottom:8px}@media(max-width:800px){.metrics{grid-template-columns:repeat(2,1fr)}.overview{margin:12px;padding:20px}}
</style>
